FILE: app/src/label-position.ts
```ts
import type { Camera } from "@babylonjs/lite";
import {
  getViewMatrix,
  getViewProjectionMatrix,
  getEffectiveAspectRatio,
  resolveCameraViewport,
  projectWorldToScreen,
} from "@babylonjs/lite";

export function labelPosition(
  camera: Camera,
  canvas: HTMLCanvasElement,
  point: { x: number; y: number; z: number }
): { x: number; y: number; visible: boolean } {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;
  const cssWidth = canvas.clientWidth;
  const cssHeight = canvas.clientHeight;

  const aspectRatio = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspectRatio);
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);

  const result = projectWorldToScreen(point, view, viewProjection, {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
  });

  return {
    x: result.cssX,
    y: result.cssY,
    visible: !result.behindCamera && !result.offscreen,
  };
}
```

I wrote `src/label-position.ts` which uses the library's `projectWorldToScreen` to transform the world-space point into CSS-pixel screen coordinates, then derives `visible` as "not behind the camera and not offscreen" (ignoring the far-clip flag, per your spec that distant mountains beyond the far plane still count as visible). The one thing I'm not 100% sure of is whether `clientWidth`/`clientHeight` is the right source for CSS dimensions versus `getBoundingClientRect()` — I chose `clientWidth`/`clientHeight` because the spec says "CSS pixels from the canvas's top-left corner," which matches the layout box, but if your canvas uses CSS transforms you may want to switch to `getBoundingClientRect()`.
